import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        if len(S) != N:
            pass

        freq = {}
        for c in S:
            freq[c] = freq.get(c, 0) + 1

        odd_count = 0
        for count in freq.values():
            if count % 2 == 1:
                odd_count += 1

        if N % 2 == 0 and odd_count > 0:
            print("NO")
            continue
        elif N % 2 == 1 and odd_count > 1:
            print("NO")
            continue

        print("YES")

        s_list = list(S)
        n = len(s_list)
        left = 0
        right = n - 1
        ops = 0

        while left < right:
            if s_list[left] == s_list[right]:
                left += 1
                right -= 1
                continue

            l = left
            r = right

            found_left_match = False
            found_right_match = False

            k = right - 1
            while k > left:
                if s_list[k] == s_list[left]:
                    found_left_match = True
                    break
                k -= 1

            if not found_left_match:
                k = left + 1
                while k < right:
                    if s_list[k] == s_list[right]:
                        found_right_match = True
                        break
                    k += 1

            if found_left_match and found_right_match:
                cost_l = right - k
                cost_r = k - left

                if cost_l < cost_r:
                    while k < right:
                        s_list[k], s_list[k+1] = s_list[k+1], s_list[k]
                        ops += 1
                        k += 1
                    left += 1
                    right -= 1
                else:
                    while k > left:
                        s_list[k], s_list[k-1] = s_list[k-1], s_list[k]
                        ops += 1
                        k -= 1
                    left += 1
                    right -= 1
            elif found_left_match:
                while k < right:
                    s_list[k], s_list[k+1] = s_list[k+0], s_list[k+1]
                    s_list[k], s_list[k+1] = s_list[0], s_list[1]
                    ops += 1
                    k += 1
                left += 1
                right -= 1
            elif found_right_match:
                while k > left:
                    s_list[k], s_list[k-1] = s_list[k-0], s_list[k-1]
                    s_list[k], s_list[k-1] = s_list[-1], s_list[-2]
                    ops += 1
                    k -= 1
                left += 1
                right -= 1
        print(ops)

